-- Migration 191: честные средние LTV когорты + прочерк непрожитых окон
-- БД: YC analytics. Накат: node migrations/run_local.mjs migrations/191_cohort_ltv_matured.sql --db=analytics
--
-- Аудит владельца 03.09 («почему у Бибикова 33 млн за всё время и по 25 за
-- 60 и 90 — значит уже 50?»). Сверка на живых данных (строка Бибикова сошлась
-- до рубля): суммы окон корректны, но семантика была недообъяснена и среднее
-- считалось нечестно:
--  1. В окно N входят ТОЛЬКО клиенты, прожившие N дней с первой отгрузки
--     (решение 17.08). У Бибикова LTV-30 собран по 23 клиентам, LTV-60 — по 22,
--     LTV-90 — по 18, LTV-180 — по 3, LTV-360 — по 0. Колонки НЕ сравнимы друг
--     с другом и НЕ складываются (окна накопительные: 60 включает 30).
--  2. Средние LTV делили сумму по прожившим на ВСЕХ повторных (24) — занижение.
--     Новые скрытые метрики cohort_matured_N (прожившие повторные) — знаменатели.
--  3. Непрожитое окно показывало «0 ₽» — теперь NULL, прочерк (код движка).
--  4. Тексты «?» переписаны под реальную семантику.

BEGIN;

INSERT INTO metrics (id, name_ru, name_short_ru, category, metric_type, data_type,
                     decimal_places, aggregation_fn, sort_order, is_active, is_hidden_in_ui,
                     description, human_description, formula_human)
VALUES
  ('cohort_matured_30', 'Повторные клиенты, прожившие 30 дней (служебная)', 'Прожили 30 дн',
   'Клиенты', 'external', 'int', 0, 'sum', 1613, true, true,
   $mtxt$Служебный знаменатель «LTV за 30 дней (среднее)» (миграция 191): повторные клиенты когорты, чья первая отгрузка была ≥ 30 дней назад — ровно те, чья выручка входит в cohort_repeat_revenue_30.$mtxt$,
   $mtxt$Считаем повторных клиентов когорты (первая товарная отгрузка в периоде, 2+ отгрузки за историю), у которых окно 30 дней от первой отгрузки уже прожито. Только их выручка входит в «LTV за 30 дней» — и среднее делится на них же.$mtxt$,
   $mtxt$= число повторных клиентов когорты, чья первая отгрузка была не позже, чем 30 дней назад$mtxt$),
