UPDATE metrics SET
  formula = '[cohort_repeat_revenue_30] / [cohort_matured_30]',
  dependencies = ARRAY['cohort_repeat_revenue_30','cohort_matured_30'],
  formula_human = $mtxt$= «LTV за 30 дней» ÷ «Повторные клиенты, прожившие 30 дней». Средний накопленный чек клиента за первые 30 дней жизни — по клиентам, чьё окно уже прожито$mtxt$
 WHERE id = 'cohort_ltv_30';
UPDATE metrics SET
  formula_human = $mtxt$= сумма (₽) товарных отгрузок за первые 30 дней жизни клиента (включая первую отгрузку) — ТОЛЬКО по повторным клиентам когорты, уже прожившим 30 дней. Окна накопительные (60 включает 30), но колонки между собой не сравнимы: у каждого окна своё число проживших. Прочерк — никто ещё не прожил окно$mtxt$,
  human_description = $mtxt$Когорта — заказчики, чья ПЕРВАЯ товарная отгрузка попала в период; берём из них повторных (2+ отгрузки за историю). Для каждого клиента складываем его отгрузки за первые 30 дней с момента первой (включая её саму). В сумму строки входят ТОЛЬКО клиенты, чьё окно 30 дней уже прожито (первая отгрузка была ≥ 30 дней назад) — свежие клиенты с недожитым окном не занижают сумму, поэтому соседние окна собраны по разному числу клиентов и не обязаны расти слева направо. Сколько клиентов прожило окно — служебная метрика «Повторные клиенты, прожившие 30 дней». Прочерк = ни один клиент когорты ещё не прожил окно.$mtxt$
 WHERE id = 'cohort_repeat_revenue_30';
